mapper.select:
SELECT 
FROM tb_complaint_master m
INNER JOIN tb_site s ON s.site_id = m.site_id
WHERE m.delete_yn = 'N'

  AND m.site_id = #{siteId}


  AND m.use_yn = #{useYn}


  AND (m.master_name LIKE CONCAT('%',#{keyword},'%')
    OR m.master_code LIKE CONCAT('%',#{keyword},'%'))

ORDER BY m.created_at DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM tb_complaint_master m WHERE m.delete_yn = 'N'
AND m.site_id = #{siteId}
AND m.use_yn = #{useYn}
AND (m.master_name LIKE CONCAT('%',#{keyword},'%') OR m.master_code LIKE CONCAT('%',#{keyword},'%'))

SELECT COUNT(*) > 0
FROM tb_complaint_master
WHERE site_id    = #{siteId}
  AND master_code = #{masterCode}
  AND delete_yn  = 'N'

  AND complaint_master_id != #{excludeId}
